import{z as o,x as n,o as e,c as B,q as t,j as A,D as a,d as i,s as r,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"MFU 优化案例","description":"","frontmatter":{"title":"MFU 优化案例","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-mfu-case.md","filePath":"llm/dist-mfu-case.md","lastUpdated":1791063341000}'),d={name:"llm/dist-mfu-case.md"};function m(p,E,D,F,h,c){const l=n("Mermaid");return e(),B("div",null,[E[2]||(E[2]=t('<h1 id="mfu-优化案例" tabindex="-1">MFU 优化案例 <a class="header-anchor" href="#mfu-优化案例" aria-label="Permalink to &quot;MFU 优化案例&quot;">​</a></h1><div class="epigraph"><p>MFU 是把 step time 分解到不能再分解之后的余数，不是可以直接拧的旋钮；能拧的是通信、重计算、内核与重叠。</p><footer>—— 据 Korthikanti 等 2022 与 Jiang 等 2024 的报告口径整理</footer></div><p><a href="/llm/dist-fault-elastic">上一课</a>把故障当常态管起来；假设机器都在跑，step time 里有多少是白付的，就是本课的问题。本课用一个案例走一遍 MFU 优化的完整路径：从定义的口径坑，到分解清单，到按性价比排刀序。前面各课是零件，这里组装。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MFU 等于模型 FLOPs 除以「卡数乘峰值 FLOPs 乘 step time」。它的分母里藏着全部浪费，但分子先有口径坑：模型 FLOPs 算不算注意力的二次项、算不算重计算的增量，各报告不一致——满层重计算让真实计算多三成，名义 MFU 却把它算成自己的成绩。跨报告比较前先对齐两件事：分子口径（哪些项计入）与峰值口径（ dense 还是稀疏）。口径不齐时，55 与 40 两个数字没有可比性。</p><p><span class="marginnote">「峰值 FLOPs」是厂商标的理论最大浮点算力，比如 H100 的 bf16 稠密口径约 990 TFLOPS、稀疏口径翻倍——这本身就是口径坑之一。拿它当分母，MFU 永远到不了 1：等待、通信、搬数据全都藏在分母的 step time 里。</span></p><h3 id="案例走一遍" tabindex="-1">案例走一遍 <a class="header-anchor" href="#案例走一遍" aria-label="Permalink to &quot;案例走一遍&quot;">​</a></h3><p>设定：70B 模型，两千卡，MFU 四成出头，目标是五成。第一步不是调参，是分解：拿一小时的 trace 把 step time 拆成四份——通信暴露、重计算增量、数据等待、内核低效。假设拆出来是：通信暴露 8%，重计算增量折合 12%，数据等待 3%，剩余是有效计算。排刀序按性价比：先把重计算从满层降到选择性（上一课的口径，长序列下常省一半增量），成本只是改配置；再把 DP 梯度归约与反向的重叠补全、桶大小按 trace 重排（重叠课的四类结构逐一对）；数据等待看 dataloader 预取深度与分片均匀度；最后才动内核——融合与 tile 是上游库的事，自己改的维护成本最高。</p>',8)),(e(),A(s,null,{default:a(()=>[r(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22step%20time%20100%25%22%5D%20--%3E%20E%5B%22%E6%9C%89%E6%95%88%E8%AE%A1%E7%AE%97%E7%BA%A6%2077%25%22%5D%0A%20%20T%20--%3E%20C%5B%22%E9%80%9A%E4%BF%A1%E6%9A%B4%E9%9C%B2%208%25%22%5D%0A%20%20T%20--%3E%20R%5B%22%E9%87%8D%E8%AE%A1%E7%AE%97%E5%A2%9E%E9%87%8F%2012%25%22%5D%0A%20%20T%20--%3E%20D%5B%22%E6%95%B0%E6%8D%AE%E7%AD%89%E5%BE%85%203%25%22%5D%0A%20%20R%20--%3E%7C%22%E6%BB%A1%E5%B1%82%E9%99%8D%E4%B8%BA%E9%80%89%E6%8B%A9%E6%80%A7%2C%20%E5%B8%B8%E7%9C%81%E4%B8%80%E5%8D%8A%22%7C%20E%0A%20%20C%20--%3E%7C%22%E8%A1%A5%E5%85%A8%E9%87%8D%E5%8F%A0%E4%B8%8E%E6%A1%B6%E9%87%8D%E6%8E%92%22%7C%20E%0A%20%20D%20--%3E%7C%22%E9%A2%84%E5%8F%96%E5%8A%A0%E6%B7%B1%E4%B8%8E%E5%88%86%E7%89%87%E5%9D%87%E5%8C%80%22%7C%20E%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<p><span class="marginnote">「满层重计算多三成」可以代数字验证：正常一步是前向 1 份加反向 2 份共 3 份计算；满层重算等于把前向再做一遍，变成 4 份——4/3 约等于 1.33，正好多三成。这也是为什么「关重计算」提分最快：直接少算一整份。</span></p><p><span class="marginnote">公开报告的高位口径：MegaScale 在千卡级报过五成五的量级，Llama 3 在 H100 上报过四成量级——两者分子口径不同，直接比数字没有意义。同一集群内的纵向比较才是 MFU 的正当用法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把分解做成固定动作：每次优化候选先回答「省的是哪一项、预期多少、怎么验证」。验证用三个数：P99 step time（不是均值）、MFU 分项表（通信、重计算、数据、内核各占多少）、以及 loss 曲线对拍（确认优化没改变数值语义）。改重叠与改重计算的验证成本低，当周可做；改内核与切分的验证成本高，排进版本计划。每一次改动记进实验台账：假设、改动、三个验证数、回退条件——这与实验管理课的台账是同一本。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么 MFU 有上限：气泡与不可重叠的层内通信是结构性的，TP 的关键路径交换、PP 的残余空拍，都只能压缩不能消除；公开报告的高位停在五成到六成之间，逼近上限的过程是边际收益递减——从四成到四成五改配置，从五成五往上动内核。为什么 MFU 不该当唯一目标：它不度量损失质量与成本，一个把全局 batch 推到 roofline 拐点之外（口径见<a href="/llm/batch-roofline-knee">批大小与 roofline 拐点</a>）的配置可以抬 MFU 却伤收敛步数；MoE 负载不均时，热专家把全组按住，平均 MFU 看不见，要看 P99（落后者的分解见<a href="/llm/straggler-mitigation">落后者缓解</a>）。</p><p><span class="marginnote">MoE 里的「平均 MFU」像「平均工资」：一个热专家（token 都往它那儿挤）按住全组等它算完，其他卡闲着，平均数却还看得过去。所以要看 P99——最慢那张卡的分解，瓶颈就藏在那里。</span></p>',7)),(e(),A(s,null,{default:a(()=>[r(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22MFU%20%E4%BD%8E%22%5D%20--%3E%20DEF%7B%22%E5%88%86%E5%AD%90%E4%B8%8E%E5%B3%B0%E5%80%BC%E5%8F%A3%E5%BE%84%E5%AF%B9%E9%BD%90%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20DEF%20--%3E%7C%E6%B2%A1%E6%9C%89%7C%20ALIGN%5B%22%E5%85%88%E7%BB%9F%E4%B8%80%E5%8F%A3%E5%BE%84%2C%20%E5%86%8D%E8%B0%88%E6%95%B0%E5%AD%97%22%5D%0A%20%20DEF%20--%3E%7C%E5%AF%B9%E9%BD%90%7C%20SPLIT%5B%22trace%20%E5%88%86%E8%A7%A3%3A%20%E9%80%9A%E4%BF%A1%20%2F%20%E9%87%8D%E8%AE%A1%E7%AE%97%20%2F%20%E6%95%B0%E6%8D%AE%20%2F%20%E5%86%85%E6%A0%B8%22%5D%0A%20%20SPLIT%20--%3E%20RANK%5B%22%E6%8C%89%E6%80%A7%E4%BB%B7%E6%AF%94%E6%8E%92%E5%88%80%E5%BA%8F%22%5D%0A%20%20RANK%20--%3E%20A%5B%22%E9%80%89%E6%8B%A9%E6%80%A7%E9%87%8D%E8%AE%A1%E7%AE%97%E9%99%8D%E5%A2%9E%E9%87%8F%22%5D%0A%20%20RANK%20--%3E%20B%5B%22%E8%A1%A5%E5%85%A8%E9%87%8D%E5%8F%A0%E4%B8%8E%E6%A1%B6%E9%87%8D%E6%8E%92%22%5D%0A%20%20RANK%20--%3E%20C%5B%22%E6%95%B0%E6%8D%AE%E9%A2%84%E5%8F%96%E4%B8%8E%E5%88%86%E7%89%87%E5%9D%87%E5%8C%80%22%5D%0A%20%20RANK%20--%3E%20D%5B%22%E5%86%85%E6%A0%B8%E8%9E%8D%E5%90%88%E4%B8%8E%20tile%22%5D%0A%20%20A%20--%3E%20V%5B%22P99%20%2B%20%E5%88%86%E9%A1%B9%E8%A1%A8%20%2B%20loss%20%E5%AF%B9%E6%8B%8D%2C%20%E8%AE%B0%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20B%20--%3E%20V%0A%20%20C%20--%3E%20V%0A%20%20D%20--%3E%20V%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲各项的机制：通信暴露见重叠课，重计算见上一课，内核层的基础见 <a href="/llm/megatron-core">Megatron-Core</a> 与内核工程课程，FP8 带来的算力分母变化见 <a href="/llm/fp8-training">FP8 训练（Transformer Engine）</a>。MFU 不度量故障与恢复的折损，那在容错课的账里。跨代硬件比较 MFU 前先确认峰值口径与带宽比，否则第一课的「带宽换算」就把结论带偏。案例的数字是示例路径，不是配额。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MFU 的分子与峰值各有口径坑；跨报告比较前先对齐，同集群纵向比较才是正当用法。</li><li>优化从分解开始：trace 拆成通信暴露、重计算增量、数据等待、内核低效四份。</li><li>刀序按性价比：先配置（重计算粒度、重叠、数据），后内核；每刀带假设、验证数与回退条件。</li><li>验证看 P99 step time、MFU 分项表、loss 对拍三个数，不只看均值。</li><li>出处：Korthikanti 等 2022 的重计算口径；Jiang 等，MegaScale，2024；Llama 3 技术报告的吞吐口径。</li></ul>',4))])}const C=o(d,[["render",m]]);export{_ as __pageData,C as default};
